package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URI;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

final class GzipFileSystemMutaGate1Test {
  @Test
  void constructor_storesArgumentsAndConfiguresGzipFileSystem() {
    GzipFileSystemProvider provider = new GzipFileSystemProvider();
    Path gzipPath = Path.of("some-dir", "archive.gz");
    Path tempFile = Path.of("some-dir", "payload.tmp");
    URI uri = URI.create("gzip:archive.gz");

    GzipFileSystem fs = new GzipFileSystem(provider, uri, gzipPath, "entry.txt", tempFile);

    assertSame(provider, fs.provider());
    assertSame(gzipPath, fs.gzipFile());
    assertSame(gzipPath, fs.hostArchivePath());
    assertEquals("entry.txt", fs.virtualEntryName());
    assertSame(tempFile, fs.uncompressedTempFile());
    assertEquals("gzip:" + gzipPath, fs.toString());
    assertEquals(SingleEntryArchiveFormat.GZIP, fs.pathFormat());

    ReadOnlyCompressorFileStore store = fs.gzipFileStore();
    assertNotNull(store);
    assertSame(store, fs.compressorFileStore());
    assertEquals("gzip", store.type());

    assertTrue(fs.isOpen());
    assertTrue(fs.isReadOnly());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertSame;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;
import org.junit.jupiter.api.Test;

final class GzipFileSystemMutaGate2Test {
  @Test
  void provider_returnsSameProviderInstanceThatCreatedFileSystem() throws IOException {
    Path gzPath = Files.createTempFile("tarballfs-test-", ".gz");
    try {
      try (OutputStream out = Files.newOutputStream(gzPath);
          GzipCompressorOutputStream gzOut = new GzipCompressorOutputStream(out)) {
        gzOut.write("hello".getBytes(StandardCharsets.UTF_8));
      }

      GzipFileSystemProvider provider = new GzipFileSystemProvider();
      URI uri = URI.create("gzip:" + gzPath.toAbsolutePath());
      FileSystem fs = provider.newFileSystem(uri, Map.of());
      try {
        GzipFileSystem gzipFs = (GzipFileSystem) fs;
        GzipFileSystemProvider typed = gzipFs.provider();
        assertSame(provider, typed);
        assertSame(provider, fs.provider());
        assertSame(provider, gzipFs.getPath("/").getFileSystem().provider());
      } finally {
        fs.close();
      }
    } finally {
      Files.deleteIfExists(gzPath);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.FileSystemNotFoundException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;
import org.junit.jupiter.api.Test;

final class GzipFileSystemMutaGate3Test {
  @Test
  void close_deregistersUri_soItCanBeReopenedAndIsNoLongerLookedUp() throws IOException {
    Path gzPath = Files.createTempFile("tarballfs-test-", ".gz");
    try {
      byte[] data = "hello".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(gzPath);
          GzipCompressorOutputStream gzOut = new GzipCompressorOutputStream(out)) {
        gzOut.write(data);
      }

      GzipFileSystemProvider provider = new GzipFileSystemProvider();
      URI uri = URI.create("gzip:" + gzPath.toAbsolutePath());

      FileSystem first = provider.newFileSystem(uri, Map.of());
      assertTrue(first.isOpen());
      first.close();
      assertTrue(!first.isOpen());

      assertThrows(FileSystemNotFoundException.class, () -> provider.getFileSystem(uri));

      FileSystem second = provider.newFileSystem(uri, Map.of());
      try {
        assertNotNull(second);
        assertNotSame(first, second);
        assertTrue(second.isOpen());
      } finally {
        second.close();
      }
    } finally {
      Files.deleteIfExists(gzPath);
    }
  }
}

